    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0xFCB10B9EDBD32735ULL + 0xF48DB06533F0A7E8ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0x9393A61D85AF24ABULL + 0x8C6ADF0D7801C912ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseA(pNonce * 0x9291FEC5323E483FULL + 0xCD3902A92667F736ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseC(pNonce * 0x8E4C0D5C91546507ULL + 0xF7A9098804D03754ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseC(pNonce * 0xE38ACDCAB3CD9B59ULL + 0x8F27D8F5BF787020ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseB(pNonce * 0xC67C067DBA6254DFULL + 0xE6223CA91C81FCE6ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseA(pNonce * 0xDF63FDDF3C8D68B1ULL + 0xCB6D23A2624D740CULL);
    [[maybe_unused]] const std::uint64_t aNonceWordH = TwistMix64::DiffuseA(pNonce * 0x8010C26C1E9AB1D3ULL + 0xA1CC40CEC89C2625ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordI = TwistMix64::DiffuseC(pNonce * 0xA1730347C0E83FBFULL + 0xA3847A672EAEC96AULL);
    [[maybe_unused]] const std::uint64_t aNonceWordJ = TwistMix64::DiffuseA(pNonce * 0xE2282753B6B2BCDBULL + 0x9A0EA4191325BFA1ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordK = TwistMix64::DiffuseA(pNonce * 0x8D701F584D3F9D55ULL + 0x8515E2AD442B76E4ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordL = TwistMix64::DiffuseC(pNonce * 0xAC1A5D88E841F8F1ULL + 0x99D2C9E529BBE124ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordM = TwistMix64::DiffuseC(pNonce * 0x935B96CC3C94ECC5ULL + 0xCA8721611ABFB5DCULL);
    [[maybe_unused]] const std::uint64_t aNonceWordN = TwistMix64::DiffuseB(pNonce * 0xC5AE33BD7D4E38C5ULL + 0xFFB76CE38FED21F4ULL);
