            aCross = RotL64(aNonceLane[((S_BLOCK1 - aIndex + 2699U)) & S_BLOCK1], 5U) ^ RotL64(aSource[((S_BLOCK1 - aIndex + 5371U)) & S_BLOCK1], 51U);
            aCross = TwistMix64::DiffuseC(((aCross ^ aDomainWordCross) ^ aNonceWordH));
            //
            aScatter = (RotL64(aPrevious, 57U) ^ RotL64(aCross, 5U)) ^ (RotL64(aIngress, 26U) + RotL64(aCarry, 41U));
            aScatter = TwistMix64::DiffuseC(((aScatter ^ aDomainWordScatter) ^ aNonceWordJ));
