            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 28299U)) & S_BLOCK1], 36U) ^ RotL64(aWaterLaneD[((S_BLOCK1 - aIndex + 28306U)) & S_BLOCK1], 5U));
