            //
            aOrbiterD = ((aWandererJ + RotL64(aPrevious, 11U)) + 0xF72A35B42E065E60ULL) + aTwistOrbiterAssignSaltD[((aIndex + 187U)) & S_SALT1];
            aOrbiterC = ((aWandererK + RotL64(aIngress, 35U)) + RotL64(aCarry, 35U)) + 0xB259DDD995232C8EULL;
            aOrbiterK = ((aWandererD + RotL64(aScatter, 3U)) + RotL64(aCarry, 53U)) + 0x40E984664A8A5B27ULL;
            aOrbiterH = (aWandererB + RotL64(aCross, 27U)) + 0x844830D1890F834AULL;
            aOrbiterJ = ((aWandererI + RotL64(aScatter, 56U)) + 0xA558915A33434A58ULL) + aTwistOrbiterAssignSaltE[((aIndex + 151U)) & S_SALT1];
            aOrbiterB = (aWandererF + RotL64(aIngress, 47U)) + 0xFADD1884206AFD73ULL;
            aOrbiterF = ((aWandererG + RotL64(aCross, 21U)) + RotL64(aCarry, 3U)) + 0xF10A8EEB3F8E88E8ULL;
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0xDBCC9D95C3A98444ULL;
