            aOrbiterC = RotL64((aOrbiterC * 0x66C661146C3CE851ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0xC976AEA5AE790F51ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterB) ^ 0x0B8A29711687EFB8ULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 208U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xFAD67A63FAA08889ULL), 29U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0xBB1629551CD23C2FULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0xD5A77CC838A1E89EULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xA2895A9CC9E2E491ULL), 51U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0x2043A7AAD917D739ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0x410D9AFEABDF3387ULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 148U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x628F2B17B3BA64CDULL), 43U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterB) + 0x65470C8FC37B8718ULL) + aTwistOrbiterUpdateSaltA[(((255U - aIndex) + 126U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterJ) ^ 0xF521995EFAB44764ULL) ^ aTwistOrbiterUpdateSaltD[(((255U - aIndex) + 65U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x8181F87042E9B487ULL), 37U);
            //
            aIngress = RotL64(aOrbiterC, 5U) ^ aOrbiterK;
            aIngress = aIngress + (RotL64(aOrbiterJ, 19U) ^ aOrbiterH);
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterD, 57U));
            aIngress = aIngress + RotL64(aOrbiterB, 51U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererF = aWandererF + (((RotL64(aCross, 51U) + aOrbiterC) + RotL64(aOrbiterH, 13U)) + RotL64(aCarry, 5U));
            aWandererB = aWandererB ^ ((RotL64(aIngress, 60U) + aOrbiterD) + RotL64(aOrbiterC, 19U));
            aWandererJ = aWandererJ + (((RotL64(aScatter, 5U) + aOrbiterF) + RotL64(aOrbiterC, 51U)) + RotL64(aCarry, 47U));
            aWandererI = aWandererI ^ (((RotL64(aPrevious, 29U) + RotL64(aOrbiterB, 30U)) + aOrbiterF) + aTwistWandererUpdateSaltC[((aIndex + 255U)) & S_SALT1]);
            aWandererG = aWandererG + ((RotL64(aScatter, 35U) + aOrbiterK) + RotL64(aOrbiterH, 43U));
