            //
            aIngress = (RotL64(aLightningLaneA[((aIndex + 7843U)) & S_BLOCK1], 13U) ^ RotL64(aHeartLaneC[((aIndex + 8412U)) & S_BLOCK1], 58U));
            aIngress ^= (RotL64(aFireLaneD[((aIndex + 6245U)) & S_BLOCK1], 35U) ^ RotL64(aEarthLaneA[((aIndex + 9246U)) & S_BLOCK1], 47U));
            aIngress = TwistMix64::DiffuseA((aIngress ^ aTwistDomainWordIngress));
