            aCross = TwistMix64::DiffuseB((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aIngress, 57U) ^ RotL64(aCarry, 41U)) ^ (RotL64(aPrevious, 13U) + RotL64(aCross, 28U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterE = ((aWandererF + RotL64(aPrevious, 6U)) + RotL64(aCarry, 35U)) + 0x0DA925642356306EULL;
            aOrbiterG = ((aWandererG + RotL64(aIngress, 19U)) + 0xD8F9EAA5839AB0B2ULL) + aTwistOrbiterAssignSaltA[((aIndex + 195U)) & S_SALT1];
