            aWandererB = aWandererB + ((((RotL64(aCross, 3U) + aOrbiterC) + RotL64(aOrbiterK, 13U)) + RotL64(aCarry, 3U)) + aTwistWandererUpdateSaltF[((aIndex + 97U)) & S_SALT1]);
