            aOrbiterB = (((aWandererC + RotL64(aCross, 12U)) + RotL64(aCarry, 43U)) + 0xD51725A090ACCB32ULL) + aTwistOrbiterAssignSaltA[(((255U - aIndex) + 145U)) & S_SALT1];
            aOrbiterC = ((aWandererJ + RotL64(aScatter, 51U)) + RotL64(aCarry, 29U)) + 0x739041D19336727BULL;
