            aOrbiterD = ((aOrbiterD + aOrbiterH) + 0x520C84DF376BFB6CULL) + aTwistOrbiterUpdateSaltC[((aIndex + 237U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterD) ^ 0x171123C4A7E6DFACULL) ^ aTwistOrbiterUpdateSaltA[(((255U - aIndex) + 110U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xBA7DD05874747E79ULL), 19U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0xD9D03F5F629DA675ULL;
