            aOrbiterF = RotL64((aOrbiterF * 0x205B366536EC5991ULL), 29U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterJ) + 0x7E09A070B61E0303ULL) + aTwistOrbiterUpdateSaltD[(((255U - aIndex) + 175U)) & S_SALT1];
