            aWandererA = aWandererA ^ ((RotL64(aScatter, 5U) + RotL64(aOrbiterF, 13U)) + aOrbiterK);
            aWandererB = aWandererB + (((RotL64(aIngress, 13U) + aOrbiterH) + RotL64(aOrbiterJ, 57U)) + RotL64(aCarry, 53U));
            aWandererG = aWandererG ^ (((RotL64(aCross, 19U) + aOrbiterA) + RotL64(aOrbiterH, 47U)) + aTwistWandererUpdateSaltD[((aIndex + 48U)) & S_SALT1]);
