            aOrbiterJ = ((aWandererJ + RotL64(aScatter, 35U)) + RotL64(aCarry, 47U)) + 0x5220D90609DEC2C7ULL;
            aOrbiterA = (((aWandererE + RotL64(aPrevious, 10U)) + RotL64(aCarry, 57U)) + 0x2C11D993C7CFC6E6ULL) + aKeyRotateBOrbiterAssignSaltF[(((255U - aIndex) + 204U)) & S_SALT1];
